-- ---------------------------------------------------------------------------
-- 036_bookkeeping_program.sql
-- Adds the Bookkeeping NC III program to the catalog (id: bookkeeping).
--
-- The baseline supabase/schema.sql seeds the catalog, but it only runs once on
-- a fresh project. Run this file on an existing database to publish the new
-- course without re-seeding the other programs.
--
-- Idempotent: re-running upserts the same row.
-- ---------------------------------------------------------------------------

insert into public.programs (id, code, title, trainer_id, data)
values ('bookkeeping', 'BK-612', 'Bookkeeping NC III', null, $prog${"id":"bookkeeping","code":"BK-612","title":"Bookkeeping NC III","category":"Business & Finance","level":"NC III","special":false,"enrollable":false,"description":"Record business transactions, maintain ledgers, prepare trial balances and produce financial statements for small and medium enterprises.","overview":"The Bookkeeping NC III program prepares trainees to keep complete and accurate books of accounts. It covers accounting fundamentals, journalizing and posting, the trial balance and adjusting entries, and the preparation of financial statements, bank reconciliation and payroll records for a business enterprise.","duration":"3 months","hours":180,"fee":9000,"color":"from-slate-700 to-slate-900","image":"/courses/bookkeeping.jpg","coverBackground":true,"requirements":["At least 18 years old","High School graduate or ALS equivalent","Basic numeracy and computer skills","Birth certificate (PSA)","2 pcs. 2x2 ID picture","Barangay clearance"],"trainerId":null,"competencies":[{"id":"bookkeeping-basic","type":"Basic","title":"Basic Competency","description":"Foundational skills required of every trainee: communication, numeracy, digital literacy and workplace behavior.","lessons":[{"videoUrl":"","published":true,"order":1,"id":"bookkeeping-basic-l1","title":"Reading, Writing & Comprehension","description":"Develop the ability to read, interpret and write workplace documents, forms and simple reports.","duration":45,"video":"Introduction to Workplace Literacy","materials":[{"id":"bookkeeping-basic-l1-m1","name":"Reading Comprehension Guide.pdf","type":"pdf","url":""},{"id":"bookkeeping-basic-l1-m2","name":"Workplace Forms Template.docx","type":"doc","url":""}],"content":"This lesson builds the foundational literacy skills needed in a technical-vocational workplace. You will practice reading instructions, interpreting forms, and writing simple reports and messages clearly and accurately.","quizId":"bookkeeping-basic-l1-quiz"},{"videoUrl":"","published":true,"order":2,"id":"bookkeeping-basic-l2","title":"Basic Communication Skills","description":"Learn verbal and non-verbal communication techniques for professional workplace interaction.","duration":40,"video":"Effective Workplace Communication","materials":[{"id":"bookkeeping-basic-l2-m1","name":"Communication Etiquette Handout.pdf","type":"pdf","url":""}],"content":"Communication is the backbone of any workplace. This lesson covers active listening, professional tone, giving and receiving feedback, and adapting your communication style to different audiences.","quizId":"bookkeeping-basic-l2-quiz"},{"videoUrl":"","published":true,"order":3,"id":"bookkeeping-basic-l3","title":"Basic Digital Literacy","description":"Familiarize yourself with computers, the internet, email and basic productivity tools.","duration":60,"video":"Getting Started with Computers","materials":[{"id":"bookkeeping-basic-l3-m1","name":"Digital Skills Workbook.pdf","type":"pdf","url":""},{"id":"bookkeeping-basic-l3-m2","name":"Keyboard Shortcuts Cheatsheet.pdf","type":"pdf","url":""}],"content":"Digital literacy is essential for modern employment. This lesson introduces operating systems, file management, internet browsing, email, and cloud-based productivity tools.","quizId":"bookkeeping-basic-l3-quiz"},{"videoUrl":"","published":true,"order":4,"id":"bookkeeping-basic-l4","title":"Workplace Behavior & Professionalism","description":"Understand workplace ethics, punctuality, grooming, and professional conduct.","duration":35,"video":"Professional Conduct at Work","materials":[{"id":"bookkeeping-basic-l4-m1","name":"Code of Conduct.pdf","type":"pdf","url":""}],"content":"Professionalism covers punctuality, appropriate attire, respect for colleagues, following rules and regulations, and taking responsibility for your work.","quizId":"bookkeeping-basic-l4-quiz"}]},{"id":"bookkeeping-common","type":"Common","title":"Common Competency","description":"Skills common across technical-vocational industries: workplace communication, safety, customer service and teamwork.","lessons":[{"videoUrl":"","published":true,"order":1,"id":"bookkeeping-common-l1","title":"Workplace Communication","description":"Communicate effectively with clients, colleagues and supervisors using industry-appropriate language.","duration":50,"video":"Communicating in the Workplace","materials":[{"id":"bookkeeping-common-l1-m1","name":"Communication Scenarios.pdf","type":"pdf","url":""}],"content":"This lesson focuses on industry-specific communication: handling inquiries, reporting incidents, participating in meetings, and documenting work activities.","quizId":"bookkeeping-common-l1-quiz"},{"videoUrl":"","published":true,"order":2,"id":"bookkeeping-common-l2","title":"Workplace Safety & Emergency Procedures","description":"Identify hazards, follow OSH standards, and respond to workplace emergencies.","duration":55,"video":"Occupational Safety and Health","materials":[{"id":"bookkeeping-common-l2-m1","name":"OSH Standards Manual.pdf","type":"pdf","url":""},{"id":"bookkeeping-common-l2-m2","name":"Emergency Evacuation Plan.pdf","type":"pdf","url":""}],"content":"Occupational Safety and Health (OSH) is a legal requirement. Learn to identify hazards, use protective equipment, follow safety signage, and respond to emergencies such as fire, earthquake, and medical incidents.","quizId":"bookkeeping-common-l2-quiz"},{"videoUrl":"","published":true,"order":3,"id":"bookkeeping-common-l3","title":"Customer Service Excellence","description":"Deliver quality service that meets and exceeds customer expectations.","duration":45,"video":"Service Quality Standards","materials":[{"id":"bookkeeping-common-l3-m1","name":"Customer Service Standards.pdf","type":"pdf","url":""}],"content":"Excellent customer service builds loyalty and reputation. Learn the principles of service quality, handling complaints, and creating positive customer experiences.","quizId":"bookkeeping-common-l3-quiz"},{"videoUrl":"","published":true,"order":4,"id":"bookkeeping-common-l4","title":"Working with Others & Time Management","description":"Collaborate effectively in teams and manage your time and priorities.","duration":40,"video":"Teamwork and Productivity","materials":[{"id":"bookkeeping-common-l4-m1","name":"Teamwork Activity Sheet.pdf","type":"pdf","url":""}],"content":"Success in the workplace depends on teamwork and personal productivity. This lesson covers collaboration, conflict resolution, prioritization, and effective scheduling.","quizId":"bookkeeping-common-l4-quiz"}]},{"id":"bookkeeping-core","type":"Core","title":"Core Competency","description":"Core competencies of Bookkeeping NC III: accounting fundamentals, recording business transactions, posting and the trial balance, and preparing financial reports.","lessons":[],"units":[{"id":"bookkeeping-core-u1","title":"Accounting Fundamentals","description":"Understand the purpose of bookkeeping and the principles behind every recorded transaction.","lessons":[{"videoUrl":"","published":true,"order":1,"id":"bookkeeping-core-u1-l1","title":"Introduction to Bookkeeping & Accounting","description":"Distinguish bookkeeping from accounting and identify the duties of a bookkeeper.","duration":45,"video":"Introduction to Bookkeeping & Accounting","materials":[{"id":"bookkeeping-core-u1-l1-m1","name":"Bookkeeping Overview.pdf","type":"pdf","url":""}],"content":"Bookkeeping is the systematic recording of business transactions. This lesson covers the duties of a bookkeeper, the stages of the accounting cycle, the users of financial information, and the business records that must be kept.","quizId":"bookkeeping-core-u1-l1-quiz"},{"videoUrl":"","published":true,"order":2,"id":"bookkeeping-core-u1-l2","title":"The Accounting Equation & Double-Entry System","description":"Apply the accounting equation and the rules of debit and credit.","duration":55,"video":"The Accounting Equation & Double-Entry System","materials":[{"id":"bookkeeping-core-u1-l2-m1","name":"Accounting Equation Worksheet.xlsx","type":"xls","url":""},{"id":"bookkeeping-core-u1-l2-m2","name":"Debit and Credit Rules.pdf","type":"pdf","url":""}],"content":"Every transaction keeps the accounting equation (Assets = Liabilities + Equity) in balance. Learn the rules of debit and credit for assets, liabilities, equity, revenue and expenses, and analyze transactions using the double-entry system.","quizId":"bookkeeping-core-u1-l2-quiz"},{"videoUrl":"","published":true,"order":3,"id":"bookkeeping-core-u1-l3","title":"Accounting Concepts & the Accounting Cycle","description":"Identify the assumptions, principles and steps that guide financial recording.","duration":50,"video":"Accounting Concepts & the Accounting Cycle","materials":[{"id":"bookkeeping-core-u1-l3-m1","name":"Accounting Cycle Diagram.pdf","type":"pdf","url":""}],"content":"Study the fundamental concepts — accrual, going concern, matching, consistency and materiality — and walk through the full accounting cycle from source documents to the closing entries.","quizId":"bookkeeping-core-u1-l3-quiz"}]},{"id":"bookkeeping-core-u2","title":"Recording Business Transactions","description":"Analyze source documents and record transactions in the books of accounts.","lessons":[{"videoUrl":"","published":true,"order":1,"id":"bookkeeping-core-u2-l1","title":"Source Documents & the Chart of Accounts","description":"Verify business documents and classify accounts correctly.","duration":50,"video":"Source Documents & the Chart of Accounts","materials":[{"id":"bookkeeping-core-u2-l1-m1","name":"Sample Source Documents.pdf","type":"pdf","url":""}],"content":"Learn to check invoices, receipts, vouchers and statements for completeness and accuracy, then assign each transaction to the proper account using a well-designed chart of accounts.","quizId":"bookkeeping-core-u2-l1-quiz"},{"videoUrl":"","published":true,"order":2,"id":"bookkeeping-core-u2-l2","title":"Journalizing in the General Journal","description":"Record transactions chronologically with correct debits and credits.","duration":60,"video":"Journalizing in the General Journal","materials":[{"id":"bookkeeping-core-u2-l2-m1","name":"General Journal Template.xlsx","type":"xls","url":""}],"content":"Practice recording entries in the general journal: date, account titles, debit and credit amounts, and a short explanation. Covers compound entries and correcting entries.","quizId":"bookkeeping-core-u2-l2-quiz"},{"videoUrl":"","published":true,"order":3,"id":"bookkeeping-core-u2-l3","title":"Special Journals & Subsidiary Ledgers","description":"Use special journals and subsidiary records for high-volume transactions.","duration":55,"video":"Special Journals & Subsidiary Ledgers","materials":[{"id":"bookkeeping-core-u2-l3-m1","name":"Special Journals Guide.pdf","type":"pdf","url":""}],"content":"Learn how the sales, purchases, cash receipts and cash payments journals simplify recording, and how subsidiary ledgers track individual customers and suppliers.","quizId":"bookkeeping-core-u2-l3-quiz"}]},{"id":"bookkeeping-core-u3","title":"Posting & the Trial Balance","description":"Transfer journal entries to the ledger and prove the accuracy of the records.","lessons":[{"videoUrl":"","published":true,"order":1,"id":"bookkeeping-core-u3-l1","title":"Posting to the General Ledger","description":"Post journal entries to the correct ledger accounts.","duration":55,"video":"Posting to the General Ledger","materials":[{"id":"bookkeeping-core-u3-l1-m1","name":"Ledger Posting Practice.xlsx","type":"xls","url":""}],"content":"Follow the posting procedure: locate the account, enter the date, amount and journal reference, then update the running balance for each account.","quizId":"bookkeeping-core-u3-l1-quiz"},{"videoUrl":"","published":true,"order":2,"id":"bookkeeping-core-u3-l2","title":"Preparing the Trial Balance","description":"Prepare a trial balance and locate errors when it does not balance.","duration":45,"video":"Preparing the Trial Balance","materials":[{"id":"bookkeeping-core-u3-l2-m1","name":"Trial Balance Worksheet.xlsx","type":"xls","url":""}],"content":"Prepare an unadjusted trial balance listing every account and its balance, then apply techniques such as recomputing, checking postings and tracing entries to find errors.","quizId":"bookkeeping-core-u3-l2-quiz"},{"videoUrl":"","published":true,"order":3,"id":"bookkeeping-core-u3-l3","title":"Adjusting Entries & the Worksheet","description":"Record accruals, deferrals, depreciation and other period-end adjustments.","duration":60,"video":"Adjusting Entries & the Worksheet","materials":[{"id":"bookkeeping-core-u3-l3-m1","name":"Adjusting Entries Guide.pdf","type":"pdf","url":""}],"content":"Adjust the records at period end for accrued revenues and expenses, prepayments, unearned income, depreciation and inventory, and complete a worksheet to produce the adjusted trial balance.","quizId":"bookkeeping-core-u3-l3-quiz"}]},{"id":"bookkeeping-core-u4","title":"Financial Reports & Compliance","description":"Prepare financial statements and keep records compliant with reporting requirements.","lessons":[{"videoUrl":"","published":true,"order":1,"id":"bookkeeping-core-u4-l1","title":"Preparing the Income Statement","description":"Compute gross profit, operating income and net income.","duration":55,"video":"Preparing the Income Statement","materials":[{"id":"bookkeeping-core-u4-l1-m1","name":"Income Statement Template.xlsx","type":"xls","url":""}],"content":"Prepare a single-step and multi-step income statement, classify revenues and expenses, and compute gross profit, operating income and net income for the period.","quizId":"bookkeeping-core-u4-l1-quiz"},{"videoUrl":"","published":true,"order":2,"id":"bookkeeping-core-u4-l2","title":"Preparing the Statement of Financial Position","description":"Classify and present assets, liabilities and equity.","duration":55,"video":"Preparing the Statement of Financial Position","materials":[{"id":"bookkeeping-core-u4-l2-m1","name":"Statement of Financial Position Template.xlsx","type":"xls","url":""}],"content":"Prepare the statement of financial position using the classified format, distinguishing current from non-current items and presenting equity for sole proprietorships, partnerships and corporations.","quizId":"bookkeeping-core-u4-l2-quiz"},{"videoUrl":"","published":true,"order":3,"id":"bookkeeping-core-u4-l3","title":"Bank Reconciliation & Internal Control","description":"Reconcile the cash book with the bank statement and apply basic controls.","duration":50,"video":"Bank Reconciliation & Internal Control","materials":[{"id":"bookkeeping-core-u4-l3-m1","name":"Bank Reconciliation Form.xlsx","type":"xls","url":""}],"content":"Prepare a bank reconciliation by adjusting for deposits in transit, outstanding checks, bank charges and errors. Discuss segregation of duties, authorization and documentation as basic internal controls.","quizId":"bookkeeping-core-u4-l3-quiz"},{"videoUrl":"","published":true,"order":4,"id":"bookkeeping-core-u4-l4","title":"Payroll, Taxes & Record Keeping","description":"Maintain payroll records and keep books compliant and audit-ready.","duration":45,"video":"Payroll, Taxes & Record Keeping","materials":[{"id":"bookkeeping-core-u4-l4-m1","name":"Payroll Register Template.xlsx","type":"xls","url":""},{"id":"bookkeeping-core-u4-l4-m2","name":"Record Keeping Checklist.pdf","type":"pdf","url":""}],"content":"Compute gross and net pay with statutory deductions, record payroll entries, and learn the retention, safekeeping and reporting requirements for business books and records.","quizId":"bookkeeping-core-u4-l4-quiz"}]}]}],"quizzes":[{"id":"bookkeeping-basic-l1-quiz","programId":"bookkeeping","title":"Reading, Writing & Comprehension Quiz","passing":75,"timeLimit":30,"published":true,"questions":[{"id":"bookkeeping-basic-l1-quiz-q1","type":"mcq","q":"Which accounting equation is correct?","options":["Assets = Liabilities + Equity","Assets = Liabilities - Equity","Equity = Assets + Liabilities","Liabilities = Assets + Equity"],"answer":"Assets = Liabilities + Equity"},{"id":"bookkeeping-basic-l1-quiz-q2","type":"tf","q":"In double-entry bookkeeping, every transaction affects at least two accounts.","answer":true},{"id":"bookkeeping-basic-l1-quiz-q3","type":"id","q":"The left side of a T-account is called the ______ side.","answer":"debit"},{"id":"bookkeeping-basic-l1-quiz-q4","type":"mcq","q":"Which document is the source document for a sale on account?","options":["Sales invoice","Payroll register","Bank statement","Petty cash voucher"],"answer":"Sales invoice"},{"id":"bookkeeping-basic-l1-quiz-q5","type":"tf","q":"Bookkeeping and accounting mean exactly the same thing.","answer":false}],"lessonId":"bookkeeping-basic-l1"},{"id":"bookkeeping-basic-l2-quiz","programId":"bookkeeping","title":"Basic Communication Skills Quiz","passing":75,"timeLimit":30,"published":true,"questions":[{"id":"bookkeeping-basic-l2-quiz-q1","type":"mcq","q":"Which journal is used to record sales on credit?","options":["Sales journal","Cash receipts journal","General journal","Petty cash journal"],"answer":"Sales journal"},{"id":"bookkeeping-basic-l2-quiz-q2","type":"tf","q":"Posting transfers entries from the journal to the ledger.","answer":true},{"id":"bookkeeping-basic-l2-quiz-q3","type":"id","q":"A ______ is a list of all the accounts used by a business.","answer":"chart of accounts"},{"id":"bookkeeping-basic-l2-quiz-q4","type":"mcq","q":"A trial balance is prepared to:","options":["Check that total debits equal total credits","Compute net income","Record adjusting entries","Close the books"],"answer":"Check that total debits equal total credits"}],"lessonId":"bookkeeping-basic-l2"},{"id":"bookkeeping-basic-l3-quiz","programId":"bookkeeping","title":"Basic Digital Literacy Quiz","passing":75,"timeLimit":30,"published":true,"questions":[{"id":"bookkeeping-basic-l3-quiz-q1","type":"mcq","q":"Which statement reports revenues and expenses for a period?","options":["Income statement","Statement of financial position","Trial balance","General journal"],"answer":"Income statement"},{"id":"bookkeeping-basic-l3-quiz-q2","type":"tf","q":"Accumulated depreciation is a contra-asset account.","answer":true},{"id":"bookkeeping-basic-l3-quiz-q3","type":"id","q":"Assets minus liabilities equals ______.","answer":"equity"},{"id":"bookkeeping-basic-l3-quiz-q4","type":"mcq","q":"Which account appears in the statement of financial position?","options":["Accounts payable","Service revenue","Rent expense","Sales discount"],"answer":"Accounts payable"}],"lessonId":"bookkeeping-basic-l3"},{"id":"bookkeeping-basic-l4-quiz","programId":"bookkeeping","title":"Workplace Behavior & Professionalism Quiz","passing":75,"timeLimit":30,"published":true,"questions":[{"id":"bookkeeping-basic-l4-quiz-q1","type":"mcq","q":"Which accounting equation is correct?","options":["Assets = Liabilities + Equity","Assets = Liabilities - Equity","Equity = Assets + Liabilities","Liabilities = Assets + Equity"],"answer":"Assets = Liabilities + Equity"},{"id":"bookkeeping-basic-l4-quiz-q2","type":"tf","q":"In double-entry bookkeeping, every transaction affects at least two accounts.","answer":true},{"id":"bookkeeping-basic-l4-quiz-q3","type":"id","q":"The left side of a T-account is called the ______ side.","answer":"debit"},{"id":"bookkeeping-basic-l4-quiz-q4","type":"mcq","q":"Which document is the source document for a sale on account?","options":["Sales invoice","Payroll register","Bank statement","Petty cash voucher"],"answer":"Sales invoice"},{"id":"bookkeeping-basic-l4-quiz-q5","type":"tf","q":"Bookkeeping and accounting mean exactly the same thing.","answer":false}],"lessonId":"bookkeeping-basic-l4"},{"id":"bookkeeping-common-l1-quiz","programId":"bookkeeping","title":"Workplace Communication Quiz","passing":75,"timeLimit":30,"published":true,"questions":[{"id":"boo